INSERT INTO `posts` (`post_id`, `post_type`, `post_title`, `post_image`, `post_description`, `user_id`, `created_at`, `facebook_share`, `twitter_share`) VALUES
(1, 'GK', 'Yay! Febulous is live!', '', 'Now that Febulous is live, we will need the help of each of our Users to keep it up and running. \n\nPublish your posts, react to other\'s posts, keep your profile up to date, chat with other Users and do much more things to keep yourself active on Febulous.\n \nPlease do pray that Febulous becomes a success and guess what? \n\nThis is not the end, it\'s just the beginning!', 7, '2017-04-18 15:10:16', 'Yes', 'Yes'),
(2, 'Materials', 'Check out my Essay on Life!', '', 'lifeasitshouldbe.docx', 7, '2017-04-19 09:49:45', 'Yes', 'Yes'),
(3, 'Materials', 'Check out my Essay on Education!', '', 'education.docx', 7, '2017-04-19 09:54:57', 'Yes', 'Yes'),
(4, 'GK', 'A Guide to use Febulous!', '', 'Considering the fact that Febulous has a unique strategy of connecting people through an Android Application, I as it\'s developer shall take responsibility of guiding all the Users on how to use Febulous through the next few posts.\n\nThe next few posts will include a guide on using your :\n\n- Homepage\n- Profile Page\n- Messenger\n- Notifications\n- Contact Page\n- Dashboard\n- Publish/Post Page \n\nPlease do post your queries if any through the comments section of each post.', 7, '2017-04-19 10:02:29', 'Yes', 'Yes');
